def _normalize_creditor(creditor: str) -> str:
    """Case/whitespace-insensitive form used for filler-token and dedupe matching."""
    return re.sub(r"\s+", " ", (creditor or "").strip()).lower()


def is_junk_creditor_name(creditor: str) -> bool:
    name = (creditor or "").strip()
    if not name:
        return True
    if not is_plausible_creditor_line(name):
        return True
    # Bureaus emit these placeholders in any casing ("Unknown Creditor", "N/A").
    if _normalize_creditor(name) in _UNKNOWN_CREDITOR:
        return True

