def tradeline_dedupe_key(tradeline: ParsedTradeline) -> str:
    """Identity key for a tradeline: creditor casing/spacing is not significant."""
    return f"{_normalize_creditor(tradeline.creditor)}|{(tradeline.account_number or '').strip()}"


def dedupe_tradelines(tradelines: List[ParsedTradeline]) -> List[ParsedTradeline]:
    seen: set[str] = set()
    out: List[ParsedTradeline] = []
    for tl in tradelines:
        key = tradeline_dedupe_key(tl)
        if key in seen:
            continue
        seen.add(key)
        out.append(tl)
    return out

